 'A eps^(n+m T)': lambda p: p[0]*eps**(p[1]+p[2]*T),
 'A eps^n exp(-B eps)+C T eps': lambda p: p[0]*eps**p[1]*np.exp(-p[2]*eps)+p[3]*T*eps,
